string f = Tama.Args.Get(args, "titleContains", "");
var res = new List<object>();
var titles = new List<string>();
foreach (Document d in app.Documents)
{
    titles.Add(d.Title + (d.IsLinked ? " [link]" : " [open]"));
    if (d.IsFamilyDocument || !d.Title.Contains(f)) continue;
    var locs = new List<object>();
    foreach (ProjectLocation pl in d.ProjectLocations)
    {
        var pp = pl.GetProjectPosition(XYZ.Zero);
        locs.Add(new { name = pl.Name, id = pl.Id.IntegerValue, active = d.ActiveProjectLocation.Id == pl.Id,
            ew = Math.Round(pp.EastWest*0.3048,4), ns = Math.Round(pp.NorthSouth*0.3048,4),
            elev = Math.Round(pp.Elevation*0.3048,4), angle = Math.Round(pp.Angle*180/Math.PI,6) });
    }
    var bps = new FilteredElementCollector(d).OfClass(typeof(BasePoint)).Cast<BasePoint>().Select(b => new {
        survey = b.IsShared, clipped = b.Clipped, pinned = b.Pinned,
        internal_m = new[]{Math.Round(b.Position.X*0.3048,4),Math.Round(b.Position.Y*0.3048,4),Math.Round(b.Position.Z*0.3048,4)},
        shared_m = new[]{Math.Round(b.SharedPosition.X*0.3048,4),Math.Round(b.SharedPosition.Y*0.3048,4),Math.Round(b.SharedPosition.Z*0.3048,4)},
        ew_param = b.get_Parameter(BuiltInParameter.BASEPOINT_EASTWEST_PARAM)?.AsValueString(),
        ns_param = b.get_Parameter(BuiltInParameter.BASEPOINT_NORTHSOUTH_PARAM)?.AsValueString(),
        elev_param = b.get_Parameter(BuiltInParameter.BASEPOINT_ELEVATION_PARAM)?.AsValueString()
    }).ToList();
    var links = new FilteredElementCollector(d).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>().Select(li => {
        var t = li.GetTransform();
        return new { name = li.Name, origin_m = new[]{Math.Round(t.Origin.X*0.3048,4),Math.Round(t.Origin.Y*0.3048,4),Math.Round(t.Origin.Z*0.3048,4)},
            rot = Math.Round(Math.Atan2(t.BasisX.Y,t.BasisX.X)*180/Math.PI,4), mirrored = t.BasisX.CrossProduct(t.BasisY).Z < 0 };
    }).ToList();
    res.Add(new { title = d.Title, path = d.PathName, linked = d.IsLinked, workshared = d.IsWorkshared, locations = locs, basePoints = bps, links });
}
return new { openDocs = titles, matches = res };
